            if motif[tr][tc] != 2:
                continue
            for i in range(k):
                for j in range(k):
                    if motif[i][j] == 2:
                        out[tr * pitch + i][tc * pitch + j] = 2
            out[tr * pitch + tr][tc * pitch + tc] = 8

    return out
